        const AppState = { isTyping: false, currentConformer: 0, currentJobId: null };
        const BACKEND_CAPABILITIES = {
            alphafold3: { name: 'AlphaFold 3++', features: ['protein_folding', 'complex_prediction', 'ligand_binding', 'quantum_enhancement'], backend: '/api/alphafold3' },
            unimol: { name: 'UniMol Conformer', features: ['conformer_generation', 'molecular_clustering', 'qm_optimization'], backend: '/api/unimol' },
            quantum: { name: 'Quantum Enhancement', features: ['iqm_quantum', 'ibm_quantum', 'quantum_biophysical'], backend: '/api/quantum' },
            database: { name: 'AlphaFold Database', features: ['proteome_search', 'structure_download', 'comparison'], backend: '/api/database' },
            analysis: { name: 'Advanced Analysis', features: ['qm_docking', 'spectra_validation', 'aquamarine_validation'], backend: '/api/analysis' }
        };
        function buildAuthHeaders() {
            const headers = { 'Content-Type': 'application/json' };
            const token = localStorage.getItem('token');
            if (token) headers['Authorization'] = `Bearer ${token}`;
            return headers;
        }
        async function callBackendAPI(endpoint, payload) {
            try {
                const response = await fetch(endpoint, {
                    method: 'POST',
                    headers: buildAuthHeaders(),
                    body: JSON.stringify(payload)
                });
                if (!response.ok) {
                    throw new Error(`HTTP hiba: ${response.status}`);
                }
                return await response.json();
            } catch (error) {
                console.error('Backend API hívás sikertelen:', error);
                showToast(`Hiba: ${error.message}`, 'error');
                return { error: error.message };
            }
        }
        async function pollJobStatus(jobId) {
            let status = { status: 'running' };
            while (status.status === 'running') {
                status = await pollStatus(jobId);
                await new Promise(res => setTimeout(res, 5000));
            }
            if (status.status === 'failed') {
                throw new Error(status.error || 'Job sikertelen.');
            }
            return status.result;
        }
        async function pollStatus(jobId) {
            try {
                const response = await fetch(`/status/${jobId}`);
                if (!response.ok) {
